"""Reconcile exact source bytes, explicit final test selection and product custody."""
import json,hashlib,sys,os,platform,subprocess,xml.etree.ElementTree as ET
from pathlib import Path
R=Path(__file__).resolve().parents[1];REPO=R.parents[1];O=R/'05_REAL_PYTEST_COLD_JUNIT'
def dump(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
# Convert only our local staging links to relative links within this return.
links=[]
for base,dirs,files in os.walk(R,followlinks=False):
 for name in dirs+files:
  p=Path(base)/name
  if p.is_symlink():
   target=p.resolve();assert target.is_relative_to(R),(p,target)
   p.unlink();p.symlink_to(os.path.relpath(target,p.parent));links.append(dict(path=str(p.relative_to(R)),target=os.readlink(p)))
# Every inherited .py remains the exact original. Prior trace artifacts may be
# regenerated by the unchanged inherited conftest and are explicitly distinguished.
rows=[];refresh=[]
for filename in ['staged_manifest.json','selected_manifest.json','supplement_manifest.json','readonly_and_temporal_manifest.json']:
 for row in json.loads((R/'discovery'/filename).read_text()):
  p=R/row['path'];b=p.read_bytes();actual=hashlib.sha256(b).hexdigest();same=actual==row['sha256']
  if p.suffix=='.py':assert same,(row['path'],row['sha256'],actual)
  observation=dict(manifest=filename,**row,current_sha256=actual,source_bytes_unchanged=same)
  if not same:
   assert p.name=='02_ACTUAL_M4_M5_N9C_E04_NATIVE_OWNER_TRACE.json'
   observation['classification']='GENERATED_TRACE_REFRESH_BY_UNCHANGED_INHERITED_HARNESS';refresh.append(observation)
  rows.append(observation)
dump(R/'discovery/source_lineage_audit.json',dict(records=rows,inherited_code_bytes_unchanged=True,generated_trace_refreshes=refresh,internal_relative_symlinks=links))
# Explicit selection prevents initial setup errors from being counted as passes.
names=['original_e05','original_e04','original_n9c','original_publication','original_empirical','original_progressive','native_routeB_I4_FF_temporal_admission','e05r_repair_and_frozen_independent','e05s_independent','pe2_existing_comparative','f6m_repair','f6m_original35_final','wp2_final']
suites=[]
for name in names:
 p=O/(name+'.xml');parts=[x.attrib for x in ET.parse(p).getroot().iter('testsuite')]
 assert all(int(x.get(k,0))==0 for x in parts for k in ['failures','errors','skipped'])
 suites.append(dict(label=name,junit=str(p.relative_to(R)),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),results=parts))
events=sum(int(x['tests']) for s in suites for x in s['results']);assert events==597
dump(O/'final_test_selection.json',dict(suites=suites,junit_testcase_events=events,top_level_cases=586,unittest_subtests=11,failures=0,errors=0,skips=0,initial_attempts_retained_not_counted=['initial_setup_failure.json','wp2_initial.xml','initial_isolation_cold_a.log','f6m_original35.xml'],classification='IMPLEMENTER_REGRESSION_AND_PRODUCT_TESTS__NOT_INDEPENDENT_WP2_ACCEPTANCE'))
m=json.loads((R/'02_ACTUAL_NATIVE_IMPORT_AND_GIT_SHA_MANIFEST.json').read_text());m['separate_owner_import_probe']=json.loads((O/'owner_import_probe.json').read_text());dump(R/'02_ACTUAL_NATIVE_IMPORT_AND_GIT_SHA_MANIFEST.json',m)
# Full checkout and exact branch identity at publication preparation.
def git(*a):return subprocess.check_output(['git',*a],cwd=REPO).decode().strip()
dump(R/'environment_passport.json',dict(repository=git('remote','get-url','origin'),branch=git('branch','--show-current'),sealed_startup='5940793fbf87373dccd99dbc95973785a2b85aee',head_before_publication=git('rev-parse','HEAD'),tracked_startup_files=len(git('ls-files').splitlines()),skip_worktree_entries=len([x for x in git('ls-files','-v').splitlines() if x.startswith('S ')]),python=sys.version,executable=sys.executable,platform=platform.platform(),resource_preflight=dict(ordinary_usage_allowed=True,primary_used_percent=6,weekly_used_percent=1,reset_credits_used=0,paid_overflow_used=False),source_rights='PRIVATE_REPOSITORY_AND_SYNTHETIC_TEST_ONLY__NO_ORIGINAL_SURVEY_PROCESSING',actors=0,new_semantic_issuance=False,new_U_or_Epre=False))
# Manifest excludes its own bytes and future remote readback receipt to avoid a
# circular self hash. Git authenticates both when committed.
artifacts=[]
for p in sorted(R.rglob('*')):
 if p.is_file() and not p.is_symlink() and p.name not in ['artifact_manifest.json','publication_verification.json'] and '__pycache__' not in p.parts and p.name!='.DS_Store':
  b=p.read_bytes();artifacts.append(dict(path=str(p.relative_to(R)),bytes=len(b),sha256=hashlib.sha256(b).hexdigest()))
dump(R/'artifact_manifest.json',dict(artifacts=artifacts,exclusions=['artifact_manifest.json','publication_verification.json','symlinks recorded in source_lineage_audit','ignored caches and Finder metadata']))
print('Audited',len(rows),'source objects;',len(artifacts),'artifact files;',events,'passing JUnit events')
